                      <button onClick={() => this.setState({ draftLang: 'en' })} style={st(`border:0;padding:6px 10px;font-family:Silkscreen,monospace;font-size:11px;cursor:pointer;background:${s.draftLang === 'en' ? '#2e2347' : 'transparent'};color:#f1eff5`)}>EN</button>
