                    <button onClick={() => this.setState({ draft: null, pop: null })} style={st('height:46px;padding:0 16px;border-radius:10px;border:1px solid #5b3fb0;background:none;color:#f1eff5;font-size:15px;cursor:pointer')}>{S.cancel}</button>
